#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maximizeSquareArea(int m, int n, std::vector<int>& hFences, std::vector<int>& vFences) {
        long long MOD = 1000000007;
        hFences.push_back(1);
        hFences.push_back(m);
        vFences.push_back(1);
        vFences.push_back(n);
        std::sort(hFences.begin(), hFences.end());
        std::sort(vFences.begin(), vFences.end());

        std::unordered_set<int> hGaps;
        for (size_t i = 0; i < hFences.size(); ++i) {
            for (size_t j = i + 1; j < hFences.size(); ++j) {
                hGaps.insert(hFences[j] - hFences[i]);
            }
        }
        int maxSide = -1;
        for (size_t i = 0; i < vFences.size(); ++i) {
            for (size_t j = i + 1; j < vFences.size(); ++j) {
                int gap = vFences[j] - vFences[i];
                if (hGaps.count(gap)) {
                    maxSide = std::max(maxSide, gap);
                }
            }
        }
        if (maxSide == -1) return -1;
        return ((long long)maxSide * maxSide) % MOD;
    }
};

import java.util.*;

class Solution {
    public int maximizeSquareArea(int m, int n, int[] hFences, int[] vFences) {
        long MOD = 1_000_000_007L;
        int[] h = new int[hFences.length + 2];
        System.arraycopy(hFences, 0, h, 0, hFences.length);
        h[h.length - 2] = 1;
        h[h.length - 1] = m;
        Arrays.sort(h);

        int[] v = new int[vFences.length + 2];
        System.arraycopy(vFences, 0, v, 0, vFences.length);
        v[v.length - 2] = 1;
        v[v.length - 1] = n;
        Arrays.sort(v);

        Set<Integer> hGaps = new HashSet<>();
        for (int i = 0; i < h.length; i++) {
            for (int j = i + 1; j < h.length; j++) {
                hGaps.add(h[j] - h[i]);
            }
        }

        int maxSide = -1;
        for (int i = 0; i < v.length; i++) {
            for (int j = i + 1; j < v.length; j++) {
                int gap = v[j] - v[i];
                if (hGaps.contains(gap)) {
                    maxSide = Math.max(maxSide, gap);
                }
            }
        }

        if (maxSide == -1) return -1;
        return (int) (((long) maxSide * maxSide) % MOD);
    }
}

var maximizeSquareArea = function(m, n, hFences, vFences) {
    const MOD = 1000000007n;
    const h = [...hFences, 1, m].sort((a, b) => a - b);
    const v = [...vFences, 1, n].sort((a, b) => a - b);
    const hGaps = new Set();
    for (let i = 0; i < h.length; i++) {
        for (let j = i + 1; j < h.length; j++) {
            hGaps.add(h[j] - h[i]);
        }
    }
    let maxSide = -1;
    for (let i = 0; i < v.length; i++) {
        for (let j = i + 1; j < v.length; j++) {
            const gap = v[j] - v[i];
            if (hGaps.has(gap)) {
                maxSide = Math.max(maxSide, gap);
            }
        }
    }
    if (maxSide === -1) return -1;
    return Number((BigInt(maxSide) * BigInt(maxSide)) % MOD);
};
